<template><div><div class="mb-6 flex justify-between"><h1 class="text-2xl font-bold">게시판</h1><RouterLink v-if="auth.isLoggedIn" to="/boards/new" class="rounded bg-slate-900 px-4 py-2 text-white">글쓰기</RouterLink></div><div class="mb-4 flex gap-2"><input v-model="keyword" @keyup.enter="load(0)" class="flex-1 rounded border p-3" placeholder="검색"><button @click="load(0)" class="rounded border px-4">검색</button></div><div class="overflow-hidden rounded bg-white shadow"><RouterLink v-for="b in page?.content" :key="b.id" :to="`/boards/${b.id}`" class="block border-b p-5 hover:bg-slate-50"><div class="font-semibold">{{b.title}}</div><div class="text-sm text-slate-500">{{b.writerName}} · 조회 {{b.viewCount}}</div></RouterLink></div><Pagination :page="page" @change="load"/></div></template>
<script setup>import{onMounted,ref}from'vue';import{useAuthStore}from'../stores/auth';import{useBoardStore}from'../stores/board';import Pagination from'../components/Pagination.vue';const auth=useAuthStore(),store=useBoardStore(),page=ref(null),keyword=ref('');async function load(p=0){await store.load({page:p,size:10,keyword:keyword.value});page.value=store.page}onMounted(()=>load())</script>